<?php
require_once __DIR__.'/../inc/data.php';$admin=require_admin();$id=(int)($_GET['id']??$_POST['id']??0);$editing=$id>0;$pdo=db();$user=['id'=>0,'username'=>'','full_name'=>'','role'=>'employee','active'=>1,'data_scope'=>'selected'];$selectedPerm=[];$selectedCoord=[];$error='';
if($editing){$s=$pdo->prepare('SELECT * FROM users WHERE id=?');$s->execute([$id]);$user=$s->fetch();if(!$user){http_response_code(404);exit('User not found');}$selectedPerm=permissions_for_user($id,$user['role']);$selectedCoord=user_coordinators($id);}else{$selectedPerm=array_fill_keys(array_keys(PERMISSION_CATALOG),false);foreach(['overview','ageing','customers','bills','overdue','weekly'] as $k)$selectedPerm[$k]=true;}
$coords=source_coordinators();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$role=($_POST['role']??'employee')==='admin'?'admin':'employee';$active=isset($_POST['active'])?1:0;$scope=($_POST['data_scope']??'selected')==='all'?'all':'selected';$pass=$_POST['password']??'';$perms=$_POST['permissions']??[];$coordSel=$_POST['coordinators']??[];
 try{if(strlen($name)<2||!preg_match('/^[A-Za-z0-9._-]{3,40}$/',$username))throw new RuntimeException('Valid name and username required.');if(!$editing&&strlen($pass)<8)throw new RuntimeException('New users need a password of at least 8 characters.');if($editing&&$id===(int)$admin['id']){$role='admin';$active=1;$scope='all';}
  $pdo->beginTransaction();if($editing){$s=$pdo->prepare('UPDATE users SET username=?,full_name=?,role=?,active=?,data_scope=?'.($pass!==''?',password_hash=?':'').' WHERE id=?');$args=[$username,$name,$role,$active,$scope];if($pass!==''){$args[]=password_hash($pass,PASSWORD_DEFAULT);}$args[]=$id;$s->execute($args);}else{$s=$pdo->prepare('INSERT INTO users(username,password_hash,full_name,role,active,data_scope) VALUES(?,?,?,?,?,?)');$s->execute([$username,password_hash($pass,PASSWORD_DEFAULT),$name,$role,$active,$scope]);$id=(int)$pdo->lastInsertId();$editing=true;}
  $pdo->prepare('DELETE FROM user_permissions WHERE user_id=?')->execute([$id]);if($role!=='admin'){ $ins=$pdo->prepare('INSERT INTO user_permissions(user_id,permission_key,allowed) VALUES(?,?,1)');foreach(array_keys(PERMISSION_CATALOG) as $k)if(in_array($k,$perms,true))$ins->execute([$id,$k]); }
  $pdo->prepare('DELETE FROM user_coordinators WHERE user_id=?')->execute([$id]);if($role!=='admin'&&$scope==='selected'){ $ins=$pdo->prepare('INSERT INTO user_coordinators(user_id,coordinator_name) VALUES(?,?)');foreach($coordSel as $c)if(in_array($c,$coords,true))$ins->execute([$id,$c]); }
  $pdo->prepare("INSERT INTO audit_log(user_id,action,detail) VALUES(?,'user_saved',?)")->execute([$admin['id'],'User ID '.$id.' saved']);$pdo->commit();header('Location: users.php');exit;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$editing?'Edit user':'Add employee'?></title><link rel="stylesheet" href="../assets/app.css"></head><body><div class="admin-wrap"><div class="admin-head"><div><h1><?=$editing?'Edit user':'Add employee'?></h1><div class="small">Choose exactly what this account can access</div></div><a class="btn" href="users.php">Back</a></div><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><form method="post" class="card" style="width:100%;max-width:none"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="grid"><div class="field"><label>Full name</label><input name="full_name" value="<?=e($user['full_name'])?>" required></div><div class="field"><label>Username</label><input name="username" value="<?=e($user['username'])?>" required></div><div class="field"><label>Role</label><select name="role" <?=$id===(int)$admin['id']?'disabled':''?>><option value="employee" <?=$user['role']==='employee'?'selected':''?>>Employee</option><option value="admin" <?=$user['role']==='admin'?'selected':''?>>Admin</option></select><?php if($id===(int)$admin['id']):?><input type="hidden" name="role" value="admin"><?php endif;?></div><div class="field"><label><?=$editing?'New password (leave blank to keep current)':'Password'?></label><input type="password" name="password" <?=$editing?'':'required'?> autocomplete="new-password"></div></div><div class="field"><label><input type="checkbox" name="active" <?=$user['active']?'checked':''?> <?=$id===(int)$admin['id']?'disabled':''?>> Active account</label><?php if($id===(int)$admin['id']):?><input type="hidden" name="active" value="1"><?php endif;?></div>
<div class="section-title">Dashboard permissions</div><div class="checks"><?php foreach(PERMISSION_CATALOG as $k=>$label):?><div class="check"><label><input type="checkbox" name="permissions[]" value="<?=e($k)?>" <?=!empty($selectedPerm[$k])?'checked':''?> <?=$user['role']==='admin'?'disabled':''?>> <?=e($label)?></label></div><?php endforeach;?></div>
<div class="section-title">Receivables data access</div><div class="field"><label>Scope</label><select name="data_scope"><option value="all" <?=$user['data_scope']==='all'?'selected':''?>>All coordinators</option><option value="selected" <?=$user['data_scope']==='selected'?'selected':''?>>Only selected coordinators</option></select></div><div class="checks"><?php foreach($coords as $c):?><div class="check"><label><input type="checkbox" name="coordinators[]" value="<?=e($c)?>" <?=in_array($c,$selectedCoord,true)?'checked':''?>> <?=e($c)?></label></div><?php endforeach;?></div>
<div class="row between" style="margin-top:24px"><button class="btn primary">Save user</button><?php if($editing&&$id!==(int)$admin['id']):?><a class="btn danger" href="user_delete.php?id=<?=$id?>&csrf=<?=urlencode(csrf_token())?>" onclick="return confirm('Delete this user?')">Delete user</a><?php endif;?></div></form></div></body></html>
